def read_file_tool(path):
    try:
        with open(path, "r") as f:
            data = f.read()
        return {
            "content": [{"type": "text", "text": data}],
            "isError": False
        }
    except FileNotFoundError:
        return {
            "content": [{
                "type": "text",
                "text": f"File not found at path {path}. Check the path is relative to the workspace root and try again."
            }],
            "isError": True
        }
    except PermissionError:
        return {
            "content": [{
                "type": "text",
                "text": f"No permission to read {path}. Try a different file, or ask the user to change file permissions."
            }],
            "isError": True
        }
    except Exception as e:
        return {
            "content": [{
                "type": "text",
                "text": f"Unexpected error while reading {path}: {str(e)}"
            }],
            "isError": True
        }

async function callTool(name, args) {
  try {
    const result = await runTool(name, args);
    return {
      content: [{ type: "text", text: JSON.stringify(result) }],
      isError: false
    };
  } catch (err) {
    return {
      content: [{
        type: "text",
        text: `Tool ${name} failed: ${err.message}. Check that the arguments match the expected schema and try again.`
      }],
      isError: true
    };
  }
}

