def calculator_tool(operation, a, b):
    try:
        if operation == "add":
            result = a + b
        elif operation == "subtract":
            result = a - b
        elif operation == "multiply":
            result = a * b
        elif operation == "divide":
            result = a / b
        else:
            return {
                "content": [{
                    "type": "text",
                    "text": f"Unknown operation {operation}. Use add, subtract, multiply, or divide."
                }],
                "isError": True
            }
        return {
            "content": [{"type": "text", "text": str(result)}],
            "isError": False
        }
    except ZeroDivisionError:
        return {
            "content": [{
                "type": "text",
                "text": "Cannot divide by zero. Choose a non-zero value for b and call the tool again."
            }],
            "isError": True
        }
    except TypeError:
        return {
            "content": [{
                "type": "text",
                "text": "Both a and b must be numbers. Convert any string values to numbers and retry."
            }],
            "isError": True
        }
